import React from 'react';
import { Card } from '../ui/Card';

export default function ProcessSection() {
  const steps = [
    {
      number: '01',
      title: 'Plan & Architect',
      description:
        'Before writing a single line of code, I dive deep into understanding the project goals, user needs, and technical constraints.',
    },
    {
      number: '02',
      title: 'Build & Develop',
      description:
        'Build pixel-perfect user interfaces and robust backend systems in parallel. I ensure that every component—UI or API—is maintainable.',
    },
    {
      number: '03',
      title: 'Launch & Support',
      description:
        'I also provide post-launch monitoring, performance optimization, and ongoing iteration support to keep your product growing.',
    },
  ];

  return (
    <section className="py-20 container mx-auto px-6 lg:px-16">
      <div className="max-w-7xl mx-auto">
        <div className="flex items-center gap-4 mb-12">
          <span className="text-sm text-gray-400">// Process</span>
          <div className="flex-1 h-px bg-gray-600"></div>
        </div>
        <h2 className="text-4xl lg:text-5xl font-bold mb-16 text-white">My Development work Process</h2>
        <div className="grid md:grid-cols-3 gap-8">
          {steps.map((step, index) => (
            <Card key={index} className="p-8 bg-gray-900/50 border-gray-600 transition-transform duration-300 hover:scale-105">
              <div className="text-6xl font-bold text-teal-500 mb-6">{step.number}</div>
              <h3 className="text-xl font-semibold mb-4 text-white">{step.title}</h3>
              <p className="text-gray-400 leading-relaxed">{step.description}</p>
            </Card>
          ))}
        </div>
      </div>
    </section>
  );
}
